export function registerSelectCommand(program: Command): void {
  program
    .command("select")
    .description("Filter and rank Skills based on evaluation reports")
    .requiredOption("--from <path>", "Candidate Skills directory or JSON file")
    .option("--strategy <file>", "SelectStrategy YAML/JSON file")
    .option("--reports <file>", "Evaluation reports JSON file")
    .option("--min-completion <rate>", "Min completion rate (overrides strategy)")
    .option("--top-k <n>", "Return top K results")
    .option("--output <file>", "Output file (default: stdout)")
    .action((opts) => {
      try {
        // 加载 Skills
        const store = new SkillStore();
        const skills = store.loadDir(opts.from);

        // 加载报告
        let reports: SkillCompletionReport[] = [];
        if (opts.reports) {
          const raw = fs.readFileSync(opts.reports, "utf-8");
          reports = JSON.parse(raw);
        }

        // 加载策略
        let strategy: SelectStrategy = {
          filters: {},
          sortBy: "compositeScore",
          order: "desc",
        };
        if (opts.strategy) {
          strategy = loadStrategy(opts.strategy);
        }

        // 覆盖参数
        if (opts.minCompletion) {
          strategy.filters.minCompletionRate = parseFloat(opts.minCompletion);
        }
        if (opts.topK) {
          strategy.topK = parseInt(opts.topK, 10);
        }

        const result = SkillSelector.select(skills, reports, strategy);

        if (result.selected.length === 0) {
          log.warn("No skills passed the filter criteria.");
          return;
        }

        log.info(`Selected ${result.selected.length} of ${result.total} skills:`);
        printTable(
          ["Rank", "Skill ID", "Completion", "Error Rate", "Score"],
          result.selected.map((s) => [
            String(s.rank),
            s.skill.id,
            `${(s.report.summary.completionRate * 100).toFixed(1)}%`,
            `${(s.report.summary.errorRate * 100).toFixed(1)}%`,
            s.report.summary.compositeScore.toFixed(3),
          ]),
        );

        // 输出到文件
        if (opts.output) {
          const output = JSON.stringify(
            result.selected.map((s) => s.skill),
            null,
            2,
          );
          fs.writeFileSync(opts.output, output, "utf-8");
          log.success(`Results written to ${opts.output}`);
        }
      } catch (err) {
        log.error((err as Error).message);
        process.exit(1);
      }
    });
}

import { Command } from "commander";
import { OnDemandEvaluator, type OnDemandConfig } from "@eval-skills/core";
import { log } from "../utils/output.js";

export function registerTaskCommand(program: Command): void {
  program
    .command("task")
    .description("Evaluate a single task on demand")
    .requiredOption("--skill <path>", "Path to skill.json or skill directory")
    .requiredOption("--input <json>", "Input JSON string")
    .option("--judge <prompt>", "LLM judge prompt")
    .option("--schema <json>", "JSON Schema for validation")
    .option("--regex <patterns...>", "Regex patterns to match")
    .option("--custom <path>", "Path to custom scorer module")
    .option("--timeout <ms>", "Timeout in ms", "30000")
    .option("--model <name>", "LLM model name (for judge)")
    .option("--output <format>", "Output format: json|text", "text")
    .action(async (opts) => {
      try {
        let input: Record<string, unknown>;
        try {
            input = JSON.parse(opts.input);
        } catch (e) {
            throw new Error("Invalid input JSON");
        }

        let strategy: OnDemandConfig["scoringStrategy"];

        if (opts.judge) {
            strategy = { type: "llm_judge", judgePrompt: opts.judge };
        } else if (opts.schema) {
            try {
                strategy = { type: "schema", schema: JSON.parse(opts.schema) };
            } catch (e) {
                throw new Error("Invalid schema JSON");
            }
        } else if (opts.regex) {
            strategy = { type: "regex", patterns: opts.regex };
        } else if (opts.custom) {
            strategy = { type: "custom", customScorerPath: opts.custom };
        } else {
            throw new Error("One of --judge, --schema, --regex, or --custom must be provided");
        }

        const config: OnDemandConfig = {
            skillPath: opts.skill,
            input,
            scoringStrategy: strategy,
            timeoutMs: parseInt(opts.timeout, 10),
            llmConfig: opts.model ? { model: opts.model } : undefined
        };

        const evaluator = new OnDemandEvaluator();
        const result = await evaluator.evaluate(config);

        if (opts.output === "json") {
            console.log(JSON.stringify(result, null, 2));
        } else {
            log.info(`Skill: ${result.skillId}`);
            if (result.status === "pass") {
                log.success(`Status: ${result.status.toUpperCase()}`);
            } else {
                log.error(`Status: ${result.status.toUpperCase()}`);
            }
            log.info(`Score: ${result.score}`);
            log.info(`Latency: ${result.latencyMs}ms`);

            if (result.reason) {
                log.info(`Reason: ${result.reason}`);
            }
            if (result.error) {
                log.error(`Error: ${result.error}`);
            }
            if (result.output) {
                log.info(`Output: ${JSON.stringify(result.output, null, 2)}`);
            }
            if (result.usage) {
                log.info(`Tokens: ${result.usage.totalTokens} (Prompt: ${result.usage.promptTokens}, Completion: ${result.usage.completionTokens})`);
            }
        }

      } catch (err) {
        log.error(`Task evaluation failed: ${(err as Error).message}`);
        process.exit(1);
      }
    });
}

