      const report = ReportBuilder.build(skill, benchmarkId, results, 30000);

      // composite = 0.5*1.0 + 0.2*(1-1) + 0.3*(1-0) = 0.5 + 0 + 0.3 = 0.8
      expect(report.summary.compositeScore).toBeCloseTo(0.8, 2);
