/**
 * @file sandbox/SandboxExecutor.ts
 * @description 沙箱执行器抽象基类
 *
 * 定义沙箱执行器的统一接口，ProcessSandbox 和 DockerSandbox 均继承此类。
 * 提供：
 *   - 输入验证（命令注入防护、路径遍历检测）
 *   - 环境变量过滤
 *   - 输出大小限制
 *   - 违规事件收集
 */

import { EventEmitter } from "node:events";
import * as path from "node:path";
import type {
  SandboxConfig,
  SandboxResult,
  SandboxViolation,
  ViolationType,
} from "./types.js";

/** JSON-RPC 请求结构 */
export interface JsonRpcRequest {
  jsonrpc: "2.0";
  method: string;
  params: Record<string, unknown>;
  id: number;
}

/** 解析后的命令结构 */
export interface ParsedCommand {
  /** 可执行程序（如 "python3", "node"） */
  executable: string;
  /** 参数列表（如 ["skill.py"]） */
  args: string[];
  /** 工作目录 */
  cwd: string;
}

// ─── 安全规则常量 ─────────────────────────────────────────────────────────────

/** 允许运行的可执行程序白名单（不在列表中的将被拒绝） */
const ALLOWED_EXECUTABLES = new Set([
  "python3", "python", "python3.10", "python3.11", "python3.12",
  "node", "node20", "node18",
  "ruby", "ruby3",
  "php", "php8",
  "java",
  "bun",
  "deno",
  "bash", "sh",   // 谨慎：shell 需要额外检查脚本路径
]);

/** 高风险 shell 命令模式（用于检测注入） */
const SHELL_INJECTION_PATTERNS = [
  /[;&|`$(){}[\]<>]/,         // shell 特殊字符
  /\.\./,                      // 路径遍历
  /\/etc\//,                   // 系统配置目录
  /\/proc\//,                  // 进程信息
  /\/sys\//,                   // 内核接口
  /\bsudo\b/,                  // 提权命令
  /\bchmod\b|\bchown\b/,       // 权限变更
  /\bkill\b|\bpkill\b/,        // 进程终止
  /\bcurl\b|\bwget\b/,         // 网络下载（subprocess 模式下需额外审查）
  /\brm\b.*-rf/,               // 危险删除
  // /\beval\b/,               // eval 注入 (移除：路径中常见 eval 单词，且 shell: false 下无风险)
  // /\bexec\b/,               // exec 替换进程 (移除：同上)
];

/** 敏感环境变量名模式（不得泄露进沙箱） */
const SENSITIVE_ENV_PATTERNS = [
  /key/i, /secret/i, /token/i, /password/i, /passwd/i,
  /credential/i, /private/i, /auth/i, /api_key/i,
  /aws_/i, /gcp_/i, /azure_/i,
  /openai/i, /anthropic/i,
];

// ─── 抽象基类 ─────────────────────────────────────────────────────────────────

export abstract class SandboxExecutor extends EventEmitter {
  protected readonly config: SandboxConfig;
  protected readonly violations: SandboxViolation[] = [];

  constructor(config: SandboxConfig) {
    super();
    this.config = config;
  }

  // ─── 公共接口 ──────────────────────────────────────────────────────────────

  /**
   * 在沙箱中执行 JSON-RPC 调用
   * @param command   Skill 的 entrypoint 命令字符串（如 "python3 skill.py"）
   * @param skillDir  Skill 所在目录（绝对路径）
   * @param request   JSON-RPC 请求
   * @param signal    AbortSignal（来自 TaskExecutor 的软超时）
   */
  abstract execute(
    command: string,
    skillDir: string,
    request: JsonRpcRequest,
    signal?: AbortSignal,
  ): Promise<SandboxResult>;

  /** 获取本次执行中收集到的所有安全违规事件 */
  getViolations(): readonly SandboxViolation[] {
    return this.violations;
  }

  // ─── 输入验证（子类复用） ──────────────────────────────────────────────────

  /**
   * 解析并验证命令字符串
   * @throws Error 当命令不合法时（命令注入 / 不在白名单）
   */
  protected parseAndValidateCommand(command: string, skillDir: string): ParsedCommand {
    // Step 1: 清理命令字符串
    const trimmed = command.trim();

    // Step 2: 检测 shell 注入模式
    for (const pattern of SHELL_INJECTION_PATTERNS) {
      if (pattern.test(trimmed)) {
        this.recordViolation("command_injection", "critical",
          `Suspicious pattern "${pattern.source}" detected in command: "${trimmed}"`);
        throw new Error(
          `[Sandbox] Command blocked due to potential injection: "${trimmed}". ` +
          `Pattern: ${pattern.source}`
        );
      }
    }

    // Step 3: 解析命令（支持 "python3 skill.py" 或 "node /abs/path/index.js"）
    const parts = trimmed.split(/\s+/).filter(Boolean);
    if (parts.length === 0) {
      throw new Error("[Sandbox] Empty command is not allowed");
    }

    const executable = parts[0]!;
    const rawArgs = parts.slice(1);

    // Step 4: 可执行程序白名单检查
    const execBasename = path.basename(executable);
    if (!ALLOWED_EXECUTABLES.has(execBasename) && !ALLOWED_EXECUTABLES.has(executable)) {
      this.recordViolation("command_injection", "error",
        `Executable "${executable}" is not in the allowlist`);
      throw new Error(
        `[Sandbox] Executable "${executable}" is not allowed. ` +
        `Allowed: ${[...ALLOWED_EXECUTABLES].join(", ")}`
      );
    }

    // Step 5: 解析脚本参数路径（防止路径遍历）
    const resolvedArgs = rawArgs.map((arg) => {
      // 如果参数看起来像文件路径（不以 - 开头），则解析为绝对路径
      if (!arg.startsWith("-") && !arg.startsWith("--") && /[./\\]/.test(arg)) {
        const resolved = path.resolve(skillDir, arg);
        // 确保解析后的路径在 skillDir 内
        if (!resolved.startsWith(path.resolve(skillDir))) {
          this.recordViolation("path_traversal", "critical",
            `Path traversal attempt: "${arg}" resolves to "${resolved}" outside skillDir`);
          throw new Error(
            `[Sandbox] Path traversal blocked: "${arg}" is outside skill directory`
          );
        }
        return resolved;
      }
      return arg;
    });

    return {
      executable,
      args: resolvedArgs,
      cwd: skillDir,
    };
  }

  /**
   * 构建过滤后的环境变量
   * 只透传白名单中的变量，并注入配置的强制变量
   */
  protected buildSafeEnv(): Record<string, string> {
    const { allowList, inject } = this.config.env;
    const safeEnv: Record<string, string> = {};

    for (const key of allowList) {
      const value = process.env[key];
      if (value !== undefined) {
        // 双重检查：即使在白名单中，也不允许名字带敏感词
        const isSensitive = SENSITIVE_ENV_PATTERNS.some((p) => p.test(key));
        if (isSensitive) {
          this.recordViolation("env_leak", "warn",
            `Env var "${key}" is in allowList but matches sensitive pattern, skipped`);
          continue;
        }
        safeEnv[key] = value;
      }
    }

    // 注入强制变量（覆盖）
    if (inject) {
      for (const [key, value] of Object.entries(inject)) {
        safeEnv[key] = value;
      }
    }

    return safeEnv;
  }

  /**
   * 从输出 Buffer 中收集数据，超出限制时截断
   * @returns [截断后的字符串, 是否被截断]
   */
  protected collectOutput(chunks: Buffer[], maxBytes: number): [string, boolean] {
    let totalSize = 0;
    const finalChunks: Buffer[] = [];

    for (const chunk of chunks) {
      const remaining = maxBytes - totalSize;
      if (remaining <= 0) {
        this.recordViolation("output_truncated", "warn",
          `Output exceeded ${maxBytes} bytes and was truncated`);
        return [Buffer.concat(finalChunks).toString("utf-8"), true];
      }
      if (chunk.length <= remaining) {
        finalChunks.push(chunk);
        totalSize += chunk.length;
      } else {
        finalChunks.push(chunk.subarray(0, remaining));
        totalSize += remaining;
        this.recordViolation("output_truncated", "warn",
          `Output exceeded ${maxBytes} bytes and was truncated`);
        return [Buffer.concat(finalChunks).toString("utf-8"), true];
      }
    }

    return [Buffer.concat(finalChunks).toString("utf-8"), false];
  }

  /**
   * 记录安全违规事件并触发 "violation" 事件
   */
  protected recordViolation(
    type: ViolationType,
    severity: SandboxViolation["severity"],
    detail: string,
  ): void {
    const violation: SandboxViolation = {
      type,
      severity,
      detail,
      timestamp: new Date().toISOString(),
      skillId: "(unknown)",
    };
    this.violations.push(violation);
    this.emit("violation", violation);
  }

  /**
   * 构建空结果（用于错误提前返回）
   */
  protected makeErrorResult(
    error: string,
    runtimeUsed: "process" | "docker",
    startTime: number,
    extras: Partial<SandboxResult> = {},
  ): SandboxResult {
    return {
      success: false,
      stdout: "",
      stderr: "",
      exitCode: null,
      latencyMs: performance.now() - startTime,
      timedOut: false,
      oomKilled: false,
      outputTruncated: false,
      runtimeUsed,
      error,
      ...extras,
    };
  }
}

/**
 * @file sandbox/SandboxFactory.ts
 * @description 沙箱工厂 + 自动降级策略
 *
 * 职责：
 *   1. 根据 SandboxConfig.runtime 选择适当的沙箱实现
 *   2. "auto" 模式：检测 Docker 可用性，自动降级到 ProcessSandbox
 *   3. 构建并缓存单例沙箱实例（同一配置复用）
 *   4. 提供默认配置合并工具
 *
 * 降级策略（auto 模式）：
 *   ┌─────────────────────────────────────────────────┐
 *   │  Docker daemon 可访问?                          │
 *   │  YES → DockerSandbox  (强隔离，推荐)             │
 *   │  NO  → ProcessSandbox (弱隔离，打印安全警告)     │
 *   └─────────────────────────────────────────────────┘
 */

import type { SandboxConfig } from "./types.js";
import { DEFAULT_SANDBOX_CONFIG } from "./types.js";
import { ProcessSandbox } from "./ProcessSandbox.js";
import { DockerSandbox } from "./DockerSandbox.js";
import type { SandboxExecutor } from "./SandboxExecutor.js";

// ─── 工厂 ─────────────────────────────────────────────────────────────────────

export class SandboxFactory {
  /**
   * 创建沙箱实例
   *
   * @param config 沙箱配置（可以是完整配置或 Partial，会与默认配置合并）
   * @returns 对应运行时的 SandboxExecutor 实例
   */
  async createExecutor(
    config: Partial<SandboxConfig> = {},
  ): Promise<SandboxExecutor> {
    const merged = SandboxFactory.mergeWithDefaults(config);

    switch (merged.runtime) {
      case "process":
        return new ProcessSandbox(merged);

      case "docker":
        return new DockerSandbox(merged);

      case "auto":
      default:
        return this.createAuto(merged);
    }
  }

  /**
   * auto 模式：检测 Docker 可用性，自动选择实现
   */
  private async createAuto(config: SandboxConfig): Promise<SandboxExecutor> {
    const dockerSandbox = new DockerSandbox(config);

    // If already checked and cached, we could return here, but for now we check availability each time or assume caller handles lifecycle.
    // In factory pattern, we just create. 
    // To avoid repeated checks, we could cache the result of availability check in the factory instance if it was singleton, but it is not.
    // However, checking availability might be slow.
    // Ideally we should cache this decision globally or passed in.

    // For now, simple implementation:
    let dockerAvailable = false;
    try {
        dockerAvailable = await dockerSandbox.isAvailable();
    } catch {
        dockerAvailable = false;
    }

    if (dockerAvailable) {
      // console.info("[eval-skills sandbox] Docker detected — using DockerSandbox");
      return dockerSandbox;
    }

    // Docker not available, fallback
    return new ProcessSandbox(config);
  }

  /**
   * 将用户提供的 Partial<SandboxConfig> 与默认配置深度合并
   */
  static mergeWithDefaults(partial: Partial<SandboxConfig>): SandboxConfig {
    return {
      enabled: partial.enabled ?? DEFAULT_SANDBOX_CONFIG.enabled,
      runtime: partial.runtime ?? DEFAULT_SANDBOX_CONFIG.runtime,

      resources: {
        ...DEFAULT_SANDBOX_CONFIG.resources,
        ...partial.resources,
      },

      network: partial.network ?? DEFAULT_SANDBOX_CONFIG.network,

      filesystem: {
        ...DEFAULT_SANDBOX_CONFIG.filesystem,
        ...partial.filesystem,
      },

      env: {
        allowList: Array.from(new Set([
          ...DEFAULT_SANDBOX_CONFIG.env.allowList,
          ...(partial.env?.allowList ?? []),
        ])),
        inject: {
          ...DEFAULT_SANDBOX_CONFIG.env.inject,
          ...partial.env?.inject,
        },
      },

      docker: {
        ...DEFAULT_SANDBOX_CONFIG.docker,
        ...partial.docker,
      },
    };
  }

  /**
   * 快速构建"仅进程隔离"的开发模式沙箱（跳过 Docker 检测）
   */
  static createProcessSandbox(partial: Partial<SandboxConfig> = {}): ProcessSandbox {
    const merged = SandboxFactory.mergeWithDefaults({
      ...partial,
      runtime: "process",
    });
    return new ProcessSandbox(merged);
  }

  /**
   * 快速构建 Docker 沙箱（不做可用性检测，直接创建）
   */
  static createDockerSandbox(partial: Partial<SandboxConfig> = {}): DockerSandbox {
    const merged = SandboxFactory.mergeWithDefaults({
      ...partial,
      runtime: "docker",
    });
    return new DockerSandbox(merged);
  }
}

/**
 * @file sandbox/SandboxMonitor.test.ts
 * @description SandboxMonitor 单元测试
 */

import { describe, it, expect } from "vitest";
import { SandboxMonitor } from "./SandboxMonitor.js";
import type { SandboxViolation } from "./types.js";

function makeViolation(
  overrides: Partial<SandboxViolation> = {},
): SandboxViolation {
  return {
    type: "command_injection",
    severity: "critical",
    detail: "test detail",
    timestamp: new Date().toISOString(),
    skillId: "test_skill",
    ...overrides,
  };
}

describe("SandboxMonitor — stats accumulation", () => {
  it("should accumulate violation counts correctly", () => {
    const monitor = new SandboxMonitor();

    monitor.recordViolation(makeViolation({ severity: "critical" }));
    monitor.recordViolation(makeViolation({ severity: "error", type: "path_traversal" }));
    monitor.recordViolation(makeViolation({ severity: "warn", type: "output_truncated" }));

    const stats = monitor.getStats("test_skill")!;
    expect(stats.totalViolations).toBe(3);
    expect(stats.criticalCount).toBe(1);
    expect(stats.errorCount).toBe(1);
    expect(stats.warnCount).toBe(1);
    expect(stats.byType["command_injection"]).toBe(1);
    expect(stats.byType["path_traversal"]).toBe(1);
  });

  it("should track multiple skills independently", () => {
    const monitor = new SandboxMonitor();

    monitor.recordViolation(makeViolation({ skillId: "skill_a" }));
    monitor.recordViolation(makeViolation({ skillId: "skill_b" }));
    monitor.recordViolation(makeViolation({ skillId: "skill_a" }));

    const statsA = monitor.getStats("skill_a")!;
    const statsB = monitor.getStats("skill_b")!;

    expect(statsA.totalViolations).toBe(2);
    expect(statsB.totalViolations).toBe(1);
  });
});

describe("SandboxMonitor — circuit breaker", () => {
  it("should trip circuit breaker after threshold critical violations", () => {
    const monitor = new SandboxMonitor({
      circuitBreakerThreshold: 2,
    });

    const brokenEvents: any[] = [];
    monitor.on("circuit-open", (e) => brokenEvents.push(e));

    expect(monitor.isCircuitBroken("evil_skill")).toBe(false);

    monitor.recordViolation(makeViolation({ skillId: "evil_skill", severity: "critical" }));
    expect(monitor.isCircuitBroken("evil_skill")).toBe(false); // 还没到阈值

    monitor.recordViolation(makeViolation({ skillId: "evil_skill", severity: "critical" }));
    expect(monitor.isCircuitBroken("evil_skill")).toBe(true); // 达到阈值

    // 再次触发 critical
    monitor.recordViolation(makeViolation({ skillId: "evil_skill", severity: "critical" }));
    expect(monitor.isCircuitBroken("evil_skill")).toBe(true);

    expect(brokenEvents.length).toBe(1);
    expect(brokenEvents[0].skillId).toBe("evil_skill");
  });

  it("should not trip circuit breaker for non-critical violations", () => {
    const monitor = new SandboxMonitor({
      circuitBreakerThreshold: 2,
    });

    monitor.recordViolation(makeViolation({ skillId: "skill_x", severity: "warn" }));
    monitor.recordViolation(makeViolation({ skillId: "skill_x", severity: "warn" }));
    monitor.recordViolation(makeViolation({ skillId: "skill_x", severity: "error" }));

    expect(monitor.isCircuitBroken("skill_x")).toBe(false);
  });

  it("should allow manual circuit breaker reset", () => {
    const monitor = new SandboxMonitor({
      circuitBreakerThreshold: 1,
    });

    monitor.recordViolation(makeViolation({ skillId: "skill_y", severity: "critical" }));
    expect(monitor.isCircuitBroken("skill_y")).toBe(true);

    monitor.resetCircuit("skill_y");
    expect(monitor.isCircuitBroken("skill_y")).toBe(false);
  });
});

describe("SandboxMonitor — report generation", () => {
  it("should generate markdown report with violation summary", () => {
    const monitor = new SandboxMonitor({ circuitBreakerThreshold: 1 });

    monitor.recordViolation(makeViolation({ skillId: "bad_skill_1", severity: "critical" }));
    monitor.recordViolation(makeViolation({ skillId: "bad_skill_2", severity: "warn" }));

    const report = monitor.generateReport();

    expect(report).toContain("Sandbox Security Report");
    expect(report).toContain("bad_skill_1");
    expect(report).toContain("bad_skill_2");
    expect(report).toContain("BLOCKED"); // bad_skill_1 应被熔断
    expect(report).toContain("OK");  // bad_skill_2 正常
  });

  it("should return clean report when no violations", () => {
    const monitor = new SandboxMonitor();
    const report = monitor.generateReport();
    expect(report).toContain("No violations recorded");
  });
});

describe("SandboxMonitor — events", () => {
  it("should emit violation event for each record", () => {
    const monitor = new SandboxMonitor();
    const events: SandboxViolation[] = [];
    monitor.on("violation", (v) => events.push(v));

    monitor.recordViolation(makeViolation({ skillId: "skill_z" }));
    monitor.recordViolation(makeViolation({ skillId: "skill_z", severity: "warn" }));

    expect(events.length).toBe(2);
  });
});

/**
 * @file sandbox/SandboxMonitor.ts  (完整实现)
 * @description 安全违规监控器 + 熔断器
 *
 * 核心功能：
 *   1. 收集并聚合所有沙箱违规事件（按 skillId 维度统计）
 *   2. 违规熔断：某 Skill 触发 N 次 critical 违规后自动拒绝执行
 *   3. 持久化违规日志（可选，写入 NDJSON 文件）
 *   4. Webhook 报警集成
 *   5. Top offender 分析
 *   6. 违规保留策略（按时间窗口 TTL 清理）
 */

import { EventEmitter } from "node:events";
import * as fs from "node:fs";
import type { SandboxViolation, ViolationType } from "./types.js";
import type { SandboxExecutor } from "./SandboxExecutor.js";

// ─── 统计结构 ─────────────────────────────────────────────────────────────────

export interface SkillViolationStats {
  skillId: string;
  totalViolations: number;
  criticalCount: number;
  errorCount: number;
  warnCount: number;
  byType: Partial<Record<ViolationType, number>>;
  firstViolationAt: string;
  lastViolationAt: string;
  /** 是否已被熔断（超过阈值后拒绝继续执行） */
  circuitBroken: boolean;
}

export interface MonitorConfig {
  /**
   * 持久化违规日志文件路径（可选，NDJSON 格式）
   * 不设置时只在内存中保留
   */
  logFilePath?: string;

  /**
   * 每个 Skill 触发多少次 critical 违规后触发熔断
   * @default 3
   */
  circuitBreakerThreshold?: number;

  /**
   * Webhook 报警 URL（POST JSON，可选）
   * 每次 critical 违规时调用
   */
  webhookUrl?: string;

  /**
   * 违规记录保留时长（小时），超过此时间的记录自动清理
   * @default 24
   */
  retentionHours?: number;
}

// ─── 内部记录结构（含原始违规列表）──────────────────────────────────────────

interface SkillRecord {
  stats: SkillViolationStats;
  violations: SandboxViolation[];
}

// ─── SandboxMonitor ──────────────────────────────────────────────────────────

export class SandboxMonitor extends EventEmitter {
  private readonly config: Required<Omit<MonitorConfig, "logFilePath" | "webhookUrl">> & MonitorConfig;
  private readonly records = new Map<string, SkillRecord>();
  private cleanupTimer: ReturnType<typeof setInterval> | null = null;

  constructor(config: MonitorConfig = {}) {
    super();
    this.config = {
      circuitBreakerThreshold: config.circuitBreakerThreshold ?? 3,
      retentionHours: config.retentionHours ?? 24,
      logFilePath: config.logFilePath,
      webhookUrl: config.webhookUrl,
    };

    // 定期清理过期记录（每小时）
    this.cleanupTimer = setInterval(
      () => this.cleanupExpiredRecords(),
      60 * 60 * 1000,
    );
    // 不阻止进程退出
    this.cleanupTimer.unref();
  }

  // ─── 核心 API ─────────────────────────────────────────────────────────────

  /**
   * 记录一条违规事件
   */
  recordViolation(violation: SandboxViolation): void {
    const { skillId } = violation;

    if (!this.records.has(skillId)) {
      this.records.set(skillId, {
        stats: {
          skillId,
          totalViolations: 0,
          criticalCount: 0,
          errorCount: 0,
          warnCount: 0,
          byType: {},
          firstViolationAt: violation.timestamp,
          lastViolationAt: violation.timestamp,
          circuitBroken: false,
        },
        violations: [],
      });
    }

    const record = this.records.get(skillId)!;
    record.violations.push(violation);

    // 更新统计
    const stats = record.stats;
    stats.totalViolations++;
    stats.lastViolationAt = violation.timestamp;
    stats.byType[violation.type] = (stats.byType[violation.type] ?? 0) + 1;

    switch (violation.severity) {
      case "critical": stats.criticalCount++; break;
      case "error":    stats.errorCount++;    break;
      case "warn":     stats.warnCount++;     break;
    }

    // 检查熔断条件
    if (!stats.circuitBroken &&
        stats.criticalCount >= this.config.circuitBreakerThreshold) {
      stats.circuitBroken = true;
      this.emit("circuit-open", { skillId, stats });
      console.error(
        `[SandboxMonitor] 🔴 Circuit breaker OPEN for skill "${skillId}". ` +
        `${stats.criticalCount} critical violations detected. ` +
        `Further executions will be rejected.`
      );
    }

    // 持久化日志
    if (this.config.logFilePath) {
      this.appendToLog(violation);
    }

    // Webhook 报警（critical 违规立即触发）
    if (violation.severity === "critical" && this.config.webhookUrl) {
      this.sendWebhookAlert(violation).catch((err) => {
        console.warn(`[SandboxMonitor] Webhook call failed: ${err}`);
      });
    }

    this.emit("violation", violation);
  }

  /**
   * 将沙箱执行器的违规事件接入 Monitor
   * 用法：monitor.attach(sandboxExecutor, skillId)
   */
  attach(executor: SandboxExecutor, skillId: string): void {
    executor.on("violation", (v: SandboxViolation) => {
      this.recordViolation({ ...v, skillId });
    });
  }

  /**
   * 检查某 Skill 是否已被熔断
   * 使用时机：TaskExecutor 在执行前调用，若熔断则直接返回错误
   */
  isCircuitBroken(skillId: string): boolean {
    return this.records.get(skillId)?.stats.circuitBroken ?? false;
  }

  /**
   * 手动重置熔断器（运维修复后使用）
   */
  resetCircuit(skillId: string): void {
    const record = this.records.get(skillId);
    if (record) {
      record.stats.circuitBroken = false;
      record.stats.criticalCount = 0;
      this.emit("circuit-reset", { skillId });
      console.info(`[SandboxMonitor] ✅ Circuit breaker RESET for skill "${skillId}"`);
    }
  }

  /**
   * 获取某 Skill 的违规统计
   */
  getStats(skillId: string): SkillViolationStats | null {
    return this.records.get(skillId)?.stats ?? null;
  }

  /**
   * 获取所有 Skill 的违规统计
   */
  getAllStats(): SkillViolationStats[] {
    return [...this.records.values()].map((r) => ({ ...r.stats }));
  }

  /**
   * 获取违规最多的 Top-K Skill（降序）
   */
  getTopOffenders(k = 10): SkillViolationStats[] {
    return this.getAllStats()
      .sort((a, b) => b.totalViolations - a.totalViolations)
      .slice(0, k);
  }

  /**
   * 获取某 Skill 的原始违规列表
   */
  getViolations(skillId: string): readonly SandboxViolation[] {
    return this.records.get(skillId)?.violations ?? [];
  }

  /**
   * 清空某 Skill 的记录（完全重置）
   */
  clearSkill(skillId: string): void {
    this.records.delete(skillId);
  }

  /**
   * 清空所有记录
   */
  clearAll(): void {
    this.records.clear();
  }

  /**
   * 生成 Markdown 格式的违规报告
   */
  generateReport(): string {
    const stats = this.getAllStats().sort((a, b) => b.totalViolations - a.totalViolations);

    if (stats.length === 0) {
      return "## 🛡️ Sandbox Security Report\n\nNo violations recorded.\n";
    }

    const circuitBrokenSkills = stats.filter((s) => s.circuitBroken);

    let md = "## 🛡️ Sandbox Security Report\n\n";

    if (circuitBrokenSkills.length > 0) {
      md += `### 🔴 Circuit Breakers Open (${circuitBrokenSkills.length})\n\n`;
      for (const s of circuitBrokenSkills) {
        md += `- \`${s.skillId}\`: ${s.criticalCount} critical violations — **BLOCKED**\n`;
      }
      md += "\n";
    }

    md += "### 📊 Violation Summary\n\n";
    md += "| Skill ID | Total | Critical | Error | Warn | Last Violation | Status |\n";
    md += "|:---------|------:|---------:|------:|-----:|:---------------|:-------|\n";

    for (const s of stats) {
      const status = s.circuitBroken ? "🔴 BLOCKED" : "🟢 OK";
      const lastTime = s.lastViolationAt.replace("T", " ").split(".")[0];
      md += `| \`${s.skillId}\` | ${s.totalViolations} | ${s.criticalCount} | ${s.errorCount} | ${s.warnCount} | ${lastTime} | ${status} |\n`;
    }

    md += "\n### 🔍 Violation Type Distribution\n\n";
    const typeTotals: Partial<Record<ViolationType, number>> = {};
    for (const s of stats) {
      for (const [type, count] of Object.entries(s.byType) as [ViolationType, number][]) {
        typeTotals[type] = (typeTotals[type] ?? 0) + count;
      }
    }

    for (const [type, count] of Object.entries(typeTotals)) {
      md += `- **${type}**: ${count} occurrences\n`;
    }

    return md;
  }

  /**
   * 停止后台清理定时器（测试或关闭时调用）
   */
  destroy(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer);
      this.cleanupTimer = null;
    }
  }

  // ─── 私有方法 ─────────────────────────────────────────────────────────────

  /**
   * 将违规记录追加到 NDJSON 日志文件
   */
  private appendToLog(violation: SandboxViolation): void {
    try {
      const line = JSON.stringify(violation) + "\n";
      fs.appendFileSync(this.config.logFilePath!, line, "utf-8");
    } catch (err) {
      console.warn(`[SandboxMonitor] Failed to write log: ${err}`);
    }
  }

  /**
   * 发送 Webhook 报警（fire-and-forget）
   */
  private async sendWebhookAlert(violation: SandboxViolation): Promise<void> {
    const body = JSON.stringify({
      event: "sandbox_violation",
      severity: violation.severity,
      skillId: violation.skillId,
      type: violation.type,
      detail: violation.detail,
      timestamp: violation.timestamp,
    });

    await fetch(this.config.webhookUrl!, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body,
      signal: AbortSignal.timeout(5_000),
    });
  }

  /**
   * 清理超过 retentionHours 的历史记录
   */
  private cleanupExpiredRecords(): void {
    const cutoff = Date.now() - this.config.retentionHours * 60 * 60 * 1000;

    for (const [skillId, record] of this.records.entries()) {
      const lastViolation = new Date(record.stats.lastViolationAt).getTime();
      if (lastViolation < cutoff && !record.stats.circuitBroken) {
        this.records.delete(skillId);
      }
    }
  }
}

